INSERT INTO "opportunity" VALUES(19,1,1,1,1,14,19,1,NULL,2,NULL,'ACTIVE','2026-08-11',NULL,NULL,'AI Engineer','6-months','We are seeking a highly skilled AI Engineer with 8+ years of experience in Machine Learning, Generative AI, and Agentic AI to design, develop, deploy, and optimize enterprise AI solutions. The ideal candidate will have strong expertise in building scalable ML pipelines, developing multimodal AI applications, implementing LLM-powered solutions, and delivering business value through modern AI technologies. Must Have Technical Skills: 8+ years of experience in Artificial Intelligence, Machine Learning, or related fields. Strong expertise in designing, building, and optimizing Machine Learning Pipelines. Advanced Python programming skills, including: Object-Oriented Programming (OOP), Functions & Modules, Iterators & Generators, Exception Handling, Decorators, Type Hints & Data Classes, Data Structures & Algorithms, Design Patterns Hands-on experience with NumPy, Pandas, Scikit-learn, XGBoost, LightGBM, PyTorch, TensorFlow, MLflow, and Matplotlib. Strong experience with Generative AI and Agentic AI frameworks, including: LangChain, LangGraph, LlamaIndex, FAISS / Pinecone, OpenAI, Anthropic, Google Gemini APIs, LangGraph Agents Strong understanding of Large Language Models (LLMs), Retrieval-Augmented Generation (RAG), Prompt Engineering, and Vector Databases. Experience building scalable, production-ready AI applications. Excellent analytical, communication, and problem-solving skills. Roles & Responsibilities Design, develop, and deploy scalable AI and Machine Learning solutions to address complex business challenges. Build and optimize end-to-end Machine Learning Pipelines, including data ingestion, model training, deployment, and monitoring. Develop advanced Generative AI applications using Large Language Models (LLMs), RAG architectures, and AI Agents. Design and implement Agentic AI frameworks using LangGraph, LangChain, and related technologies. Build and deploy Multimodal AI applications integrating Text, Image, Audio, and Video capabilities. Collaborate with Product Managers, Business Stakeholders, Data Engineers, and Solution Architects to define AI strategies and technology roadmaps. Evaluate emerging AI technologies and recommend innovative solutions to improve business outcomes. Ensure AI platforms meet enterprise standards for Performance, Scalability, Security, Governance, and Reliability. Provide technical leadership, mentor junior engineers, and promote AI engineering best practices. Communicate technical solutions, project status, risks, and business impact effectively to stakeholders and leadership teams.','-','On-Site','8/11/2026|msr technologies|ai engineer|amex','csv','Full-time','Yearly',100000.0,130000.0,'USD','https://www.linkedin.com/jobs/view/ai-engineer-at-tata-consultancy-services-4443180311','Onsite','Sunrise','Florida','2026-09-01 20:01:24.986436','2026-09-02 11:18:14.240880');
