INSERT INTO "opportunity" VALUES(42,1,1,1,1,30,34,NULL,NULL,2,NULL,'ACTIVE','2026-07-21',NULL,NULL,'AI Engineer','6-months','Role – Python GenAI Location - Jersey City, NJ/Charlotte, NC / Dallas, TX / NYC Type: W2-Contract / Full-Time Job Description: Looking for a hands-on AI Engineer to work on a high visbility Gen AI project involving summarization and chatbot supporting a huge volume of documents from various LOBs and of various types. This position is for a self-starter with strong technical skills as well as leadership qualities and should be able to effectively communicate difficult technical concepts. Responsibilities: Leads the design, development and implementation of complex data management, storage applications, Often using new technologies. Exercises judgment within broadly defined practices and policies in selecting methods, techniques, and evaluation criterion for obtaining results. Work leadership may be provided by assigning work and resolving problems. Requires a Bachelors degree or advanced degree and /or equivalent experience in related IS/IT discipline. Excellent written and verbal communication skills coupled with ability to translate business strategy into achievable tactics. Typically over 10 years of related IT experience. Requirements: • 2+ years of professional experience as a data scientist executing end-to-end Gen AI projects using following technologies LLM Models (Llama, Mixtral, Mistral) Various inferencing mechanisms – transformer/pipeline, vllm Agentic framework: langgraph Evaluation frameworks: RAGAS, langsmith, phoenix-arize Embedding (all-MiniLM-L6-v2, all-mpnet-base-v2) LLM development framework : Langchain, LlamaIndex Rest API, FastAPI, Websockets Enterprise Redis Database, Qdrant, Cockroach Must have experience of working with Model Risk Management/Model Governance, which includes Delivering on a Gen AI project following the model governance guidelines Writing a model document Building model monitoring capabilities Strong programming experience with Python Angular experience a huge plus Experience with Slurm, Hadoop/Hive, Neo4J, Apache Spark, Kafka and MongoDB is a plus Knowledge of machine-learning techniques, classifiers and statistical methods Advanced degree, or equivalent experience, in mathematics, data science or other quantitative discipline Demonstrated success in executing high value, enterprise projects with clear articulation of benefits, costs and risk Superb communication, coaching and management skills across multiple business stakeholders and IT as well as external partners Desire to use modern technologies as a disruptive influence within the Finance domain','-','On-Site','7/21/2026|iconma llc|ai engineer|boa','csv','W2','Hourly',52.5,72.25,'USD','https://www.ziprecruiter.com/c/Precision-Technologies/Job/Python-GenAI/-in-Jersey-City,NJ?jid=3b2d0d89f21addf1','Onsite','Jersey City','New Jersey','2026-09-01 20:01:25.197756','2026-09-02 11:58:31.051806');
