INSERT INTO "opportunity" VALUES(85,1,1,1,1,26,61,11,NULL,2,NULL,'ACTIVE','2026-06-19',NULL,NULL,'AWS Data Scientist','12-months','We are looking for a highly experienced AWS Data Scientist with deep expertise in Artificial Intelligence (AI), Machine Learning (ML), and advanced Python programming to build and deploy scalable, cloud-native analytics solutions on AWS. The role requires hands-on experience across the full data science lifecycle and close collaboration with business and engineering teams. Required Skills & Qualifications · Minimum 8+ years of experience in Data Science, AI, or Machine Learning · Strong hands-on expertise in AI & ML, including supervised and unsupervised learning, NLP, or deep learning · Advanced Python programming skills, including libraries such as Pandas, NumPy, Scikit-learn, TensorFlow, PyTorch · Extensive experience with AWS, especially SageMaker, S3, Redshift, Glue, Athena, Lambda · Strong foundation in statistics, predictive modeling, and ML algorithms · Proficiency in SQL and experience with data visualization techniques · Excellent communication and stakeholder management skills Key Responsibilities · Design, develop, and deploy AI/ML models and data science solutions on AWS · Build end-to-end ML pipelines using AWS services such as SageMaker, Lambda, EC2, and ECR · Perform advanced data analysis, feature engineering, model training, and optimization using Python · Work with large-scale datasets using AWS data services including S3, Glue, Athena, and Redshift · Implement MLOps practices for model deployment, monitoring, retraining, and version control · Translate complex business problems into AI/ML-driven solutions · Ensure adherence to data security, governance, and compliance standards Preferred Qualifications · AWS Certifications (Machine Learning – Specialty or Solutions Architect) · Experience with big data technologies such as Spark · Exposure to real-time or streaming data pipelines · Background in financial services or regulated industries','-','On-Site','6/19/2026|nityo info tech|aws data scientist|vanguard','csv','Full-time',NULL,NULL,NULL,'USD','https://www.google.com/goto?url=CAEShQEB6zswFVaiZweu1GoJu9GSz-NM6BAXoVeYLFE7HznGgG9L1t_wR7kRo0oEPHDbROBZ9o3fZ-tvIloE3-n1Uim-gR0PJJfIuuEzfL5OCT0-Qse6xwKNr9nLyzZOp_JMQXvaUTW870wKBqhXWQ9aEw4NjvXmTqEv9kHpccN-iITX7CJ-EBFH','Onsite',NULL,NULL,'2026-09-01 20:01:25.474778','2026-09-02 15:26:07.116500');
