INSERT INTO "opportunity" VALUES(88,1,1,1,1,55,20,1,NULL,2,NULL,'ACTIVE','2026-06-18',NULL,NULL,'Senior AI/ML Engineer','12-months','Must Have Technical/Functional Skills Builds, trains and tunes machine learning models. Translates data science experiments into scalable, production-ready ML solutions. Key Responsibilities – Translate data science prototypes into production-grade ML services and pipelines. - Build training and inference code with reproducibility, versioning, and automated testing. - Implement scalable model serving (online/offline), batching, and latency/throughput optimization. - Integrate model lifecycle tooling (tracking, registry, deployment automation, monitoring). - Collaborate with Data Engineering on feature pipelines and data contracts. - Own production health: drift detection, performance regression, rollback strategies, and incident response. Required Qualifications - 5+ years software engineering with 2+ years shipping ML models to production. - Strong Python skills and experience with ML frameworks (TensorFlow/PyTorch). - Experience with containers and orchestration (Docker/Kubernetes) and API development. - Understanding of ML system design (data leakage, training-serving skew, drift). - CI/CD and DevOps practices applied to ML workloads (MLOps).','-','Remote','6/18/2026|okaya inc|senior ai/ml engineer|uhg','csv','Full-time','Yearly',100000.0,120000.0,'USD','https://www.linkedin.com/jobs/view/senior-ai-ml-engineer-at-tata-consultancy-services-4428767018','Onsite','Eden Prairie','Minnesota','2026-09-01 20:01:25.516747','2026-09-02 11:24:14.733680');
