INSERT INTO "opportunity" VALUES(101,1,1,1,1,7,66,1,NULL,2,NULL,'ACTIVE','2026-06-10',NULL,NULL,'Senior AI ML Engineer','12-months','Must Have Technical/Functional Skill · Strong Python expertise with experience building and deploying production-grade backend systems ·Hands-on experience developing applications using LLMs, including prompt engineering and orchestration · Proven experience with RAG architectures, embeddings, and vector databases · Experience with agentic frameworks (e.g., LangChain, LangGraph, AutoGen) · Strong system design skills with experience building and scaling cloud-based applications Roles & Responsibilities · Architect and deliver end-to-end LLM-powered applications and agentic workflows using Python · Design and implement RAG pipelines over enterprise data using embeddings and vector databases · Build multi-step, tool-using agents (planning, execution, memory) using frameworks such as LangChain · Integrate AI systems with APIs, backend services, and cloud platforms · Establish evaluation, reliability, and performance strategies (accuracy, latency, cost)','-','On-Site','6/10/2026|diverse lynx llc|senior ai ml engineer|elevance health','csv','Full-time','Yearly',140000.0,165000.0,'USD','https://jobright.ai/jobs/info/6a5e0e5d270e3033b045bb57?visit=aiml---machine-learning-engineer%2C-mind-jobs-in-united-states','Onsite','Mason','Ohio','2026-09-01 20:01:25.594847','2026-09-02 15:11:53.293144');
