INSERT INTO "opportunity" VALUES(104,1,1,1,1,NULL,16,1,NULL,1,NULL,'ACTIVE','2026-09-02',NULL,NULL,'Senior GenAI/Python Engineer','6-months','Must Have Technical/Functional Skills 5+ years of advanced professional Python development experience with production-grade coding practices. Strong hands-on experience writing clean, tested, maintainable code using typing, pytest, packaging standards, Git, CI/CD, Docker, and code review discipline. 1.5+ years of hands-on experience building GenAI / LLM applications in production using OpenAI, Azure OpenAI, Anthropic, Bedrock, or similar model APIs. Experience building LLM-powered agents, including intent classification, domain-specific agents, agentic extraction flows, and multi-step orchestration. Hands-on experience with Agentic AI frameworks or patterns such as LangChain, LangGraph, LlamaIndex, function calling, tool use, or custom orchestration. Strong experience in structured output extraction from LLMs using JSON schema enforcement, Pydantic, retry/repair strategies, and validation logic. Experience with RAG and vector search concepts including embeddings, chunking, hybrid search, reranking, entity resolution, fuzzy matching, confidence thresholds, and disambiguation flows. Working knowledge of vector databases or search platforms such as pgvector, Pinecone, Weaviate, OpenSearch, Snowflake vector functions, or equivalent. Strong API development experience using FastAPI or similar frameworks such as Flask or Django. Experience with async Python and orchestration of parallel LLM/API calls. Strong SQL skills and comfort working with large analytical datasets. Cloud environment experience, preferably Azure; AWS or GCP acceptable. Strong written and verbal communication skills, with ability to collaborate directly with engineering teams, product owners, and cross-functional stakeholders. Roles & Responsibilities Build and enhance LLM-powered agentic applications using Python. Develop intent classification, domain-specialist agent workflows, and agentic extraction pipelines for complex user questions. Build natural-language-to-structured-payload pipelines that convert user utterances into accurate JSON query payloads, including filters, exclusions, rankings, and metric selection. Integrate semantic search and vector retrieval services for embedding-based entity resolution, fuzzy matching, confidence scoring, and disambiguation flows. Design, build, and consume FastAPI-based microservices. Implement async orchestration patterns for parallel LLM calls, API calls, and downstream service integrations. Develop prompt engineering patterns, structured output enforcement, JSON schema validation, function calling, tool usage, and guardrails. Build evaluation harnesses, test sets, and regression test frameworks to measure extraction accuracy and validate prompt/model changes. Work with metadata/catalog services, entitlement-aware data access, and reporting-engine payload contracts. Collaborate with multiple platform, data, service, and product teams to deliver production-ready GenAI capabilities. Write clear technical documentation including Confluence pages, ADRs, sequence diagrams, and flow diagrams. Participate in hands-on technical evaluation, code reviews, design discussions, and production readiness reviews.','-','Remote','9/2/2026|synchrony corp|senior genai/python engineer|tbd','csv','Full-time','Yearly',90000.0,130000.0,'USD','https://www.linkedin.com/jobs/view/genai-python-senior-engineer-at-tata-consultancy-services-4456288691','Remote','Anna','Texas','2026-09-03 10:29:46.098136','2026-09-03 10:32:27.213547');
INSERT INTO "opportunity" VALUES(105,1,1,1,1,62,23,1,NULL,1,NULL,'ACTIVE','2026-09-02',NULL,NULL,'GenAI Engineer','6-months','Must Have Technical/Functional Skills: Roles & Responsibilities: Design and implement Gen AI applications using AWS Bedrock and related AWS services. Build secure, scalable, and maintainable AI workflows for enterprise use cases. Develop retrieval-augmented generation solutions that use enterprise knowledge sources effectively. Manage context windows, memory strategies, prompt composition, and grounding techniques. Integrate MCP-based tools and services to extend model capabilities and connect to enterprise systems. Collaborate with product owners, architects, data engineers, and security teams. Evaluate model outputs for quality, safety, relevance, and factual accuracy. Optimize latency, cost, and token usage across AI workloads. Create reusable prompts, agent patterns, and orchestration components. Support deployment, monitoring, logging, and continuous improvement of Gen AI systems. Strong experience with Python or Java. Hands-on experience with AWS Bedrock. Understanding of foundation models, embeddings, RAG, and vector search. Experience with prompt engineering and context management. Familiarity with MCP concepts and tool integration patterns. Experience with APIs, microservices, and cloud-native architecture. Knowledge of enterprise security, privacy, and governance requirements. Ability to evaluate model performance and improve response quality. Good communication and stakeholder collaboration skills. Generic Managerial Skills, If any Experience with LangChain, LangGraph, or similar orchestration frameworks. Experience with OpenSearch, Aurora PostgreSQL, DynamoDB, or vector databases. Knowledge of IAM, KMS, CloudWatch, Lambda, Step Functions, and API Gateway. Experience with agentic workflows and tool-calling architectures. Familiarity with software engineering best practices, testing, and CI/CD. Automotive or manufacturing domain experience is a plus.','-','On-Site','9/2/2026|synchrony systems inc|genai engineer|toyota financials','csv','Full-time','Yearly',130000.0,150000.0,'USD','https://www.linkedin.com/jobs/view/gen-ai-engineer-at-tata-consultancy-services-4460065874','Onsite','Plano','Texas','2026-09-03 10:29:46.120270','2026-09-03 10:33:55.059531');
