PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE company (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE end_client (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE imp_partner (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE interview_round (
                    id INTEGER NOT NULL PRIMARY KEY,
                    opportunity_id INTEGER NOT NULL REFERENCES opportunity(id),
                    round_number INTEGER NOT NULL DEFAULT 1,
                    scheduled_date DATE,
                    start_time TIME,
                    end_time TIME,
                    interview_mode VARCHAR(20),
                    status VARCHAR(20),
                    outcome VARCHAR(20),
                    sme_review TEXT,
                    ps_review TEXT,
                    is_final BOOLEAN,
                    notes TEXT,
                    created_at DATETIME,
                    updated_at DATETIME
                );
CREATE TABLE marketing_profile (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE opportunity (
	id INTEGER NOT NULL, 
	recruiter_id INTEGER, 
	marketing_profile_id INTEGER, 
	company_id INTEGER, 
	technology_id INTEGER, 
	end_client_id INTEGER, 
	vendor_id INTEGER, 
	imp_partner_id INTEGER, 
	prime_vendor_id INTEGER, 
	pod_id INTEGER, 
	vrm_id INTEGER, 
	status VARCHAR(50), 
	submission_date DATE, 
	confirmation_date DATE, 
	actual_start DATE, 
	position_title VARCHAR(500), 
	duration VARCHAR(100), 
	job_description TEXT, 
	csv_is_direct VARCHAR(50), 
	csv_is_remote VARCHAR(50), 
	dedupe_key VARCHAR(700), 
	source VARCHAR(20), 
	employment_type VARCHAR(30), 
	pay_rate_type VARCHAR(20), 
	pay_min FLOAT, 
	pay_max FLOAT, 
	pay_currency VARCHAR(10), 
	comp_notes TEXT, 
	work_mode VARCHAR(20), 
	onsite_city VARCHAR(120), 
	onsite_state VARCHAR(120), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(recruiter_id) REFERENCES recruiter (id), 
	FOREIGN KEY(marketing_profile_id) REFERENCES marketing_profile (id), 
	FOREIGN KEY(company_id) REFERENCES company (id), 
	FOREIGN KEY(technology_id) REFERENCES technology (id), 
	FOREIGN KEY(end_client_id) REFERENCES end_client (id), 
	FOREIGN KEY(vendor_id) REFERENCES vendor (id), 
	FOREIGN KEY(imp_partner_id) REFERENCES imp_partner (id), 
	FOREIGN KEY(prime_vendor_id) REFERENCES prime_vendor (id), 
	FOREIGN KEY(pod_id) REFERENCES pod (id), 
	FOREIGN KEY(vrm_id) REFERENCES vrm (id)
);
CREATE TABLE pod (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE prime_vendor (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE recruiter (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE reschedule_history (
	id INTEGER NOT NULL, 
	interview_round_id INTEGER NOT NULL, 
	old_date DATE, 
	old_start_time TIME, 
	old_end_time TIME, 
	new_date DATE, 
	new_start_time TIME, 
	new_end_time TIME, 
	reason TEXT, 
	changed_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(interview_round_id) REFERENCES "interview_round__old" (id)
);
CREATE TABLE technology (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE vendor (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE vrm (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE UNIQUE INDEX ix_opportunity_dedupe_key ON opportunity (dedupe_key);
CREATE INDEX ix_opportunity_submission_date ON opportunity (submission_date);
CREATE INDEX ix_interview_round_opportunity_id ON interview_round (opportunity_id);
CREATE INDEX ix_interview_round_scheduled_date ON interview_round (scheduled_date);
COMMIT;
